import { invoke } from '@tauri-apps/api/core';
import './styles.css';

type Game={id:string;title:string;platform:string;source:string;executable:string|null;favorite:boolean;status:string;total_seconds:number;installed:boolean;providers:string[];active:boolean;last_played_at:string|null;session_count:number};
type LibrarySource={game_id:string;source:string;seconds:number;private:boolean};
type Installation={id:string;provider:string;external_id:string|null;executable:string|null;install_dir:string|null;installed:boolean};
type Details={game:Game;stats:{total_seconds:number;last_14_seconds:number;last_30_seconds:number;session_count:number;average_session_seconds:number;last_played_at:string|null};installations:Installation[];recent_sessions:{id:string;started_at:string;ended_at:string|null;duration_seconds:number;provider:string|null;recovered:boolean}[]};
type Provider={id:string;name:string;detected:boolean;root_path:string|null;games_found:number;last_sync:string|null;message:string;can_launch:boolean};
type SyncOutcome={provider:string;games_found:number;games_created:number;success:boolean;message:string};
type Collection={id:string;name:string;kind:string;filter_json:string|null;game_count:number};
type Emulator={id:string;name:string;platform:string;executable:string;arguments_template:string;rom_directory:string|null;bios_directory:string|null;saves_directory:string|null;extensions:string;core:string|null;enabled:boolean};
type Rom={id:string;game_id:string;title:string;platform:string;path:string;emulator_id:string|null;hash_sha256:string|null;size_bytes:number|null;launch_args:string|null;core:string|null};
type Metadata={game_id:string;description:string|null;developer:string|null;publisher:string|null;release_date:string|null;genres:string|null;cover:string|null;hero:string|null;source:string;manual:boolean;updated_at:string};
type Stats={library_games:number;installed_games:number;never_played:number;tracked_seconds:number;imported_seconds:number;last_14_seconds:number;last_30_seconds:number;average_daily_seconds_30d:number;average_weekly_seconds_12w:number;by_provider:{name:string;seconds:number}[];by_platform:{name:string;seconds:number}[];top_games:{name:string;seconds:number}[];monthly:{label:string;seconds:number}[];yearly:{label:string;seconds:number}[]};
type Diagnostic={level:string;area:string;message:string};
type Membership={id:string;name:string;included:boolean};
type SaveBackup={id:string;emulator_id:string|null;source_path:string;backup_path:string;created_at:string};
type UpdateInfo={available:boolean;current_version:string;latest_version:string|null;notes:string|null;published_at:string|null};
type SteamAccountStatus={steam_id:string|null;api_key_configured:boolean;last_sync:string|null;owned_games:number};
type StoreSettings={ggdeals_configured:boolean;itad_configured:boolean;country:string};
type StoreCatalogItem={app_id:string;title:string;cover:string|null;price:number|null;regular:number|null;currency:string|null;discount_percent:number};
type StoreOffer={shop:string;kind:string;price:number;regular:number|null;currency:string;cut:number;url:string};
type StoreComparison={app_id:string;title:string;cover:string|null;offers:StoreOffer[];gg_url:string;note:string};

const app=document.querySelector<HTMLDivElement>('#app')!;
let games:Game[]=[];let coverIndex=new Map<string,string>();let librarySources:LibrarySource[]=[];let sourcesByGame=new Map<string,LibrarySource[]>();let selected:string|null=null;let details:Details|null=null;let view='library';let mode:'grid'|'list'='grid';let query='';let filter='all';let sourceFilter='all';let showPrivate=false;let sort='title';let libraryLimit=48;let gameFingerprint='';
const esc=(v:string)=>v.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]!));
const dur=(s:number)=>{if(!s)return '0 min';const h=Math.floor(s/3600),m=Math.floor((s%3600)/60);return h?`${h}h ${m}min`:`${m}min`};
const date=(v:string|null)=>v?new Date(v).toLocaleString('pt-BR'):'Nunca';
const providerLabel=(id:string)=>({steam:'Steam',epic:'Epic',gog:'GOG',xbox:'Xbox / Game Pass',ea:'EA',ubisoft:'Ubisoft',battlenet:'Battle.net',manual:'Manual',emulation:'Emulação',android:'Android',riot:'Riot Games',playstation:'PlayStation',psn:'PlayStation',nintendo:'Nintendo',renpy:'Ren’Py (privado)',local:'Local'} as Record<string,string>)[id]||id;
function gameSources(g:Game){return sourcesByGame.get(g.id)||[]}
function sourceHours(g:Game){if(sourceFilter==='all')return g.total_seconds;return gameSources(g).find(s=>s.source===sourceFilter)?.seconds||0}
function privateGame(g:Game){return gameSources(g).some(s=>s.private)}
function availableSources(){return [...new Set(librarySources.map(x=>x.source))].filter(x=>x!=='local'&&x!=='renpy').sort((a,b)=>providerLabel(a).localeCompare(providerLabel(b),'pt-BR'))}
function rebuildSourceIndex(){sourcesByGame=new Map();for(const x of librarySources){const current=sourcesByGame.get(x.game_id)||[];current.push(x);sourcesByGame.set(x.game_id,current)}}
const initials=(title:string)=>title.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();

function shell(){app.innerHTML=`<div class="app-shell"><aside class="rail"><div class="brand"><b>Ludex</b><span>0.9.6</span></div><nav>
${[['library','Biblioteca'],['libraries','Plataformas'],['store','Loja'],['recent','Recentes'],['favorites','Favoritos'],['installed','Instalados'],['collections','Coleções'],['emulation','Emulação'],['stats','Estatísticas'],['sync','Sincronização'],['settings','Configurações'],['diagnostics','Diagnóstico']].map(([id,n])=>`<button data-view="${id}" class="nav-btn ${view===id?'active':''}">${n}</button>`).join('')}
</nav><div class="privacy">Local-first<br><span>Sem conta obrigatória</span></div></aside><main><header class="topbar"><div><p class="eyebrow">Biblioteca universal</p><h1 id="view-title">Ludex</h1></div><div class="top-actions"><input id="search" value="${esc(query)}" placeholder="Buscar jogos"><button id="add-manual" class="ghost">+ Jogo</button></div></header><div id="content"></div></main></div><div id="modal-root"></div>`;
 document.querySelectorAll<HTMLElement>('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view!;shell();void renderView()});
 document.querySelector<HTMLInputElement>('#search')!.oninput=e=>{query=(e.target as HTMLInputElement).value;libraryLimit=48;if(['library','recent','favorites','installed'].includes(view))renderLibrary()};
 document.querySelector<HTMLButtonElement>('#add-manual')!.onclick=()=>manualModal();
}
function title(t:string){document.querySelector('#view-title')!.textContent=t}
function filteredGames(){let v=games.filter(g=>g.title.toLowerCase().includes(query.toLowerCase()));if(!showPrivate)v=v.filter(g=>!privateGame(g));if(sourceFilter!=='all')v=v.filter(g=>gameSources(g).some(s=>s.source===sourceFilter));if(view==='recent')v=v.filter(g=>g.last_played_at).sort((a,b)=>(b.last_played_at||'').localeCompare(a.last_played_at||''));if(view==='favorites'||filter==='favorite')v=v.filter(g=>g.favorite);if(view==='installed'||filter==='installed')v=v.filter(g=>g.installed);if(filter==='uninstalled')v=v.filter(g=>!g.installed);if(filter==='never')v=v.filter(g=>sourceHours(g)===0);if(filter==='completed')v=v.filter(g=>['Concluído','100%'].includes(g.status));if(filter.startsWith('provider:'))v=v.filter(g=>gameSources(g).some(s=>s.source===filter.slice(9))||g.providers.includes(filter.slice(9)));if(sort==='playtime')v.sort((a,b)=>sourceHours(b)-sourceHours(a));else if(sort==='recent')v.sort((a,b)=>(b.last_played_at||'').localeCompare(a.last_played_at||''));else v.sort((a,b)=>a.title.localeCompare(b.title));return v}
function cover(g:Game){return `<div class="cover-art ${g.active?'live':''}" data-cover-id="${g.id}"><span>${esc(initials(g.title))}</span>${g.active?'<b>EM JOGO</b>':''}</div>`}
// One indexed DB read per library refresh instead of opening SQLite for every tile.
// Resolve at most three local/Steam cover assets simultaneously off the GUI thread.
let artworkObserver:IntersectionObserver|null=null;
let artworkEpoch=0;
let artworkRunning=0;
const artworkQueue:{node:HTMLElement;value:string;epoch:number}[]=[];
const artworkCache=new Map<string,string>();
const artworkFailures=new Map<string,number>();
const ARTWORK_MAX_IN_FLIGHT=3;
function rememberArtwork(key:string,src:string){
  // Large data URIs are intentionally not retained indefinitely in JS.
  if(src.length>250_000)return;
  artworkCache.delete(key);artworkCache.set(key,src);
  if(artworkCache.size>64)artworkCache.delete(artworkCache.keys().next().value!);
}
async function artworkSrc(value:string){
  if(/^(https?:|data:|blob:)/i.test(value))return value;
  const cached=artworkCache.get(value);if(cached)return cached;
  const src=await invoke<string>('resolve_artwork',{value});
  rememberArtwork(value,src);return src;
}
function pumpArtwork(){
  while(artworkRunning<ARTWORK_MAX_IN_FLIGHT&&artworkQueue.length){
    const next=artworkQueue.shift()!;
    if(!next.node.isConnected||next.epoch!==artworkEpoch)continue;
    const failure=artworkFailures.get(next.value);
    if(failure&&Date.now()-failure<30*60*1000)continue;
    artworkRunning++;
    void (async()=>{
      try{
        const src=await artworkSrc(next.value);
        if(!next.node.isConnected||next.epoch!==artworkEpoch)return;
        const img=document.createElement('img');img.loading='lazy';img.alt='';
        img.onload=()=>{if(!next.node.isConnected)return;const initials=next.node.querySelector('span');if(initials)(initials as HTMLElement).style.display='none'};
        img.onerror=()=>{img.remove();artworkFailures.set(next.value,Date.now())};
        img.src=src;next.node.prepend(img);
      }catch{artworkFailures.set(next.value,Date.now())}
      finally{artworkRunning--;pumpArtwork()}
    })();
  }
}
async function loadCoverIndex(){
  try{coverIndex=new Map(Object.entries(await invoke<Record<string,string>>('artwork_catalog')))}
  catch{coverIndex=new Map()}
}
function hydrateArtwork(){
  artworkObserver?.disconnect();artworkQueue.length=0;artworkEpoch++;
  const epoch=artworkEpoch;
  artworkObserver=new IntersectionObserver(entries=>{
    for(const entry of entries){
      if(!entry.isIntersecting)continue;
      const node=entry.target as HTMLElement;artworkObserver?.unobserve(node);
      const id=node.dataset.coverId;const value=id?coverIndex.get(id):undefined;
      if(value){artworkQueue.push({node,value,epoch});pumpArtwork()}
    }
  },{rootMargin:'90px'});
  document.querySelectorAll<HTMLElement>('[data-cover-id]').forEach(node=>artworkObserver?.observe(node));
}

function renderLibrariesHub(){
  title('Plataformas');
  const publicGames=games.filter(g=>showPrivate||!privateGame(g));
  const kinds=availableSources().concat(librarySources.some(s=>s.private)?['renpy']:[]);
  const totals=kinds.map(source=>{
    const relevant=publicGames.filter(g=>gameSources(g).some(s=>s.source===source));
    return {source,count:relevant.length,seconds:relevant.reduce((n,g)=>n+(gameSources(g).find(s=>s.source===source)?.seconds||0),0)};
  }).sort((a,b)=>b.seconds-a.seconds);
  document.querySelector('#content')!.innerHTML=`<section class="page"><div class="page-actions"><div><h2>Bibliotecas conectadas</h2><p class="muted">Os jogos de Android, Switch, PlayStation, Xbox, Riot e PC coexistem na mesma biblioteca. Cada filtro exibe apenas as horas daquela plataforma, sem perder o tempo total.</p></div><button id="go-sync" class="primary">Importar dados Android</button></div><div class="library-hub-grid"><button class="source-card" data-source="all"><strong>Todas</strong><b>${games.filter(g=>showPrivate||!privateGame(g)).length} jogos</b><span>${dur(publicGames.reduce((n,g)=>n+g.total_seconds,0))}</span></button>${totals.map(s=>`<button class="source-card" data-source="${esc(s.source)}"><strong>${esc(providerLabel(s.source))}</strong><b>${s.count} jogos</b><span>${dur(s.seconds)}</span>${s.source==='renpy'?'<small>Privado · visível somente ao selecionar</small>':''}</button>`).join('')}</div><p class="muted">Sistemas Android como Shizuku e Usage Access são executados no celular; no Windows o Ludex utiliza os dados sincronizados, sem acesso remoto ao dispositivo.</p></section>`;
  document.querySelectorAll<HTMLElement>('[data-source]').forEach(button=>button.onclick=()=>{sourceFilter=button.dataset.source||'all';if(sourceFilter==='renpy')showPrivate=true;filter='all';view='library';shell();void renderView()});
  const sync=document.querySelector<HTMLButtonElement>('#go-sync');if(sync)sync.onclick=()=>{view='sync';shell();void renderSync()};
}

function renderLibrary(){title(view==='recent'?'Recentes':view==='favorites'?'Favoritos':view==='installed'?'Instalados':sourceFilter==='all'?'Biblioteca':providerLabel(sourceFilter));const content=document.querySelector('#content')!;const visible=filteredGames();const shown=visible.slice(0,libraryLimit);if(!games.length){content.innerHTML=`<section class="onboarding"><span class="orb">L</span><h2>Monte sua biblioteca</h2><p>O Ludex pode detectar seus launchers, importar ROMs ou cadastrar jogos portáteis sem exigir conta.</p><div><button data-go="settings" class="primary">Detectar launchers</button><button id="empty-add" class="ghost">Adicionar manualmente</button></div></section>`;(document.querySelector('[data-go="settings"]') as HTMLButtonElement).onclick=()=>{view='settings';shell();void renderView()};(document.querySelector('#empty-add') as HTMLButtonElement).onclick=()=>manualModal();return}
 content.innerHTML=`<section class="source-toolbar"><div class="source-select"><label for="source-filter">Biblioteca</label><select id="source-filter"><option value="all">Todas as plataformas</option>${availableSources().map(p=>`<option value="${esc(p)}">${esc(providerLabel(p))}</option>`).join('')}${librarySources.some(s=>s.private)?'<option value="renpy">Ren’Py (privado)</option>':''}</select></div><span class="muted">${visible.length} jogo(s) · ${dur(visible.reduce((total,g)=>total+sourceHours(g),0))}</span><label class="private-switch"><input type="checkbox" id="show-private" ${showPrivate?'checked':''}> Mostrar biblioteca privada</label><button id="show-libraries" class="ghost">Explorar plataformas</button></section><section class="toolbar"><div class="chips"><button data-filter="all">Todos</button><button data-filter="favorite">Favoritos</button><button data-filter="never">Nunca jogados</button><button data-filter="completed">Concluídos</button>${availableSources().map(p=>`<button data-filter="provider:${p}">${providerLabel(p)}</button>`).join('')}</div><div><select id="sort"><option value="title">Título</option><option value="recent">Recentes</option><option value="playtime">Mais jogados</option></select><button id="view-mode" class="icon-btn">${mode==='grid'?'☷':'▦'}</button></div></section><section class="library-layout"><div class="catalog ${mode}">${shown.map(g=>mode==='grid'?`<button class="game-tile ${selected===g.id?'selected':''}" data-game="${g.id}">${cover(g)}<strong>${esc(g.title)}</strong><small>${dur(sourceHours(g))} · ${esc(g.providers.map(providerLabel).join(' · ')||g.source)}</small></button>`:`<button class="game-row ${selected===g.id?'selected':''}" data-game="${g.id}">${cover(g)}<span><strong>${esc(g.title)}</strong><small>${esc(g.platform)} · ${esc(g.providers.map(providerLabel).join(', ')||g.source)}</small></span><b>${dur(sourceHours(g))}</b><i>${g.status}</i></button>`).join('')||'<p class="empty">Nenhum jogo corresponde aos filtros.</p>'}${visible.length>shown.length?`<button id="load-more" class="ghost load-more">Carregar mais (${shown.length}/${visible.length})</button>`:''}</div><aside id="detail-pane" class="detail-pane"></aside></section>`;
 const sourcePicker=document.querySelector<HTMLSelectElement>('#source-filter');if(sourcePicker){sourcePicker.value=sourceFilter;sourcePicker.onchange=()=>{sourceFilter=sourcePicker.value;if(sourceFilter==='renpy')showPrivate=true;libraryLimit=48;renderLibrary()}}
 const privateToggle=document.querySelector<HTMLInputElement>('#show-private');if(privateToggle)privateToggle.onchange=()=>{showPrivate=privateToggle.checked;if(!showPrivate&&sourceFilter==='renpy')sourceFilter='all';renderLibrary()};
 const librariesButton=document.querySelector<HTMLButtonElement>('#show-libraries');if(librariesButton)librariesButton.onclick=()=>{view='libraries';shell();void renderView()};
 document.querySelectorAll<HTMLElement>('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.onclick=()=>{filter=b.dataset.filter!;libraryLimit=48;renderLibrary()}});const s=document.querySelector<HTMLSelectElement>('#sort')!;s.value=sort;s.onchange=()=>{sort=s.value;libraryLimit=48;renderLibrary()};document.querySelector<HTMLButtonElement>('#view-mode')!.onclick=()=>{mode=mode==='grid'?'list':'grid';renderLibrary()};document.querySelectorAll<HTMLElement>('[data-game]').forEach(b=>b.onclick=()=>void selectGame(b.dataset.game!));const more=document.querySelector<HTMLButtonElement>('#load-more');if(more)more.onclick=()=>{libraryLimit+=48;renderLibrary()};hydrateArtwork();if(selected)void selectGame(selected,false);
}
async function selectGame(id:string,rerender=true){selected=id;details=await invoke<Details|null>('get_game_details',{gameId:id});if(!details)return;if(rerender){document.querySelectorAll<HTMLElement>('[data-game]').forEach(node=>node.classList.toggle('selected',node.dataset.game===id))}const pane=document.querySelector('#detail-pane');if(!pane)return;const g=details.game;let meta:Metadata|null=null;let memberships:Membership[]=[];try{meta=await invoke('get_metadata',{gameId:id})}catch{}try{memberships=await invoke('collection_memberships',{gameId:id})}catch{}const playable=details.installations.filter(i=>i.installed);pane.innerHTML=`<div class="detail-hero">${cover(g)}<div><span>${esc(g.platform)}</span><h2>${esc(g.title)}</h2><p>${esc(g.providers.map(providerLabel).join(' · ')||g.source)}</p></div></div><div class="detail-actions"><button id="play" class="primary" ${!g.installed||g.active?'disabled':''}>${g.active?'EM JOGO':g.installed?'JOGAR':'NÃO INSTALADO'}</button><button id="fav" class="ghost">${g.favorite?'★':'☆'}</button><select id="status">${['Quero jogar','Jogando','Pausado','Concluído','100%','Abandonado'].map(x=>`<option ${x===g.status?'selected':''}>${x}</option>`).join('')}</select></div>${playable.length>1?`<label>Instalação<select id="installation">${playable.map(i=>`<option value="${i.id}">${providerLabel(i.provider)}</option>`).join('')}</select></label>`:''}<div class="metric-grid"><span><b>${dur(g.total_seconds)}</b>Total</span><span><b>${dur(details.stats.last_14_seconds)}</b>2 semanas</span><span><b>${details.stats.session_count}</b>Sessões</span></div><div class="source-breakdown"><h3>Horas por plataforma</h3>${gameSources(g).filter(s=>s.seconds>0).sort((a,b)=>b.seconds-a.seconds).map(s=>`<div class="source-row"><span>${esc(providerLabel(s.source))}</span><b>${dur(s.seconds)}</b></div>`).join('')||'<p class="muted">Nenhum tempo informado.</p>'}</div><div class="metadata"><div class="section-head"><h3>Sobre</h3><button id="edit-meta" class="text-btn">Editar</button></div><p>${esc(meta?.description||'Sem descrição. Adicione metadata manual para manter sua biblioteca organizada.')}</p><small>${esc([meta?.developer,meta?.publisher,meta?.release_date,meta?.genres].filter(Boolean).join(' · '))}</small></div><div class="collections-inline"><h3>Coleções</h3><div class="chips">${memberships.map(c=>`<button data-membership="${c.id}" class="${c.included?'active':''}">${c.included?'✓ ':''}${esc(c.name)}</button>`).join('')||'<small>Nenhuma coleção criada.</small>'}</div></div><div class="sessions"><h3>Sessões recentes</h3>${details.recent_sessions.map(s=>`<div><span>${date(s.started_at)}<small>${providerLabel(s.provider||'local')}${s.recovered?' · recuperada':''}</small></span><b>${s.ended_at?dur(s.duration_seconds):'EM JOGO'}</b></div>`).join('')||'<p class="muted">Nenhuma sessão registrada.</p>'}</div>`;
 const play=document.querySelector<HTMLButtonElement>('#play');if(play)play.onclick=async()=>{play.disabled=true;try{const installationId=document.querySelector<HTMLSelectElement>('#installation')?.value;if(installationId)await invoke('launch_game_installation',{gameId:id,installationId});else await invoke('launch_game',{gameId:id});toast('Jogo iniciado.');}catch(e){toast(String(e),true)}setTimeout(()=>void refresh(true),1200)};
 (document.querySelector('#fav') as HTMLButtonElement).onclick=async()=>{await invoke('set_favorite',{gameId:id,value:!g.favorite});await refresh(true)};(document.querySelector('#status') as HTMLSelectElement).onchange=async e=>{await invoke('set_game_status',{gameId:id,status:(e.target as HTMLSelectElement).value});await refresh(true)};(document.querySelector('#edit-meta') as HTMLButtonElement).onclick=()=>metadataModal(g,meta);document.querySelectorAll<HTMLElement>('[data-membership]').forEach(b=>b.onclick=async()=>{const item=memberships.find(x=>x.id===b.dataset.membership);if(!item)return;await invoke('set_collection_game',{collectionId:item.id,gameId:id,add:!item.included});await selectGame(id,false)});
}
function modal(html:string){document.querySelector('#modal-root')!.innerHTML=`<div class="modal-backdrop"><div class="modal">${html}</div></div>`;document.querySelectorAll<HTMLElement>('[data-close]').forEach(b=>b.onclick=()=>document.querySelector('#modal-root')!.replaceChildren())}

function riotModal(){
  modal('<div class="modal-head"><h2>Horas históricas · Riot Games</h2><button data-close>×</button></div><form id="riot-form"><p>Importação manual de estimativas do WOL.GG e Tracker.gg. Informe o total acumulado, não somente as horas novas. Valores anteriores são substituídos.</p><label>Jogo<select name="game"><option value="lol">League of Legends · WOL.GG</option><option value="valorant">VALORANT · Tracker.gg</option></select></label><label>Horas totais<input name="hours" type="text" inputmode="decimal" placeholder="Ex.: 1250,5" required></label><label>Link do perfil (opcional)<input name="profile" type="url" placeholder="https://..."></label><small id="riot-last-import"></small><div><button id="riot-open-site" type="button" class="ghost">Abrir site de estatísticas</button><button class="primary" type="submit">Salvar horas</button></div></form>');
  const form=document.querySelector<HTMLFormElement>('#riot-form')!;
  const game=form.elements.namedItem('game') as HTMLSelectElement;
  const hours=form.elements.namedItem('hours') as HTMLInputElement;
  const profile=form.elements.namedItem('profile') as HTMLInputElement;
  const last=document.querySelector('#riot-last-import')!;
  const load=async()=>{try{const [seconds,url,updated]=await invoke<[number,string|null,string|null]>('riot_playtime',{gameKey:game.value});hours.value=updated?(seconds/3600).toFixed(6).replace(/0+$/,'').replace(/\.$/,''):'';profile.value=url||'';last.textContent='Última importação: '+date(updated);}catch(e){toast(String(e),true)}};
  game.onchange=()=>void load();
  (document.querySelector('#riot-open-site') as HTMLButtonElement).onclick=()=>void invoke('open_external_url',{url:game.value==='lol'?'https://wol.gg/':'https://tracker.gg/valorant'}).catch(e=>toast(String(e),true));
  form.onsubmit=async e=>{e.preventDefault();const value=Number(hours.value.trim().replace(',','.'));if(!Number.isFinite(value)||value<0||value>1000000){toast('Informe um total válido entre 0 e 1.000.000 horas.',true);return}const seconds=Math.round(value*3600);try{await invoke('save_riot_playtime',{gameKey:game.value,seconds,profileUrl:profile.value.trim()||null});document.querySelector('#modal-root')!.replaceChildren();toast('Horas Riot salvas.');await refresh()}catch(err){toast(String(err),true)}};
  void load();
}

function manualModal(){modal(`<div class="modal-head"><h2>Adicionar jogo</h2><button data-close>×</button></div><form id="manual-form"><label>Nome<input name="title" required></label><label>Plataforma<input name="platform" value="PC"></label><label>Executável<input name="executable" placeholder="C:\\Games\\game.exe"></label><label>Diretório de trabalho<input name="working"></label><label>Argumentos<input name="args"></label><button class="primary">Adicionar</button></form>`);(document.querySelector('#manual-form') as HTMLFormElement).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);try{await invoke('add_manual_game',{title:f.get('title'),platform:f.get('platform'),executable:f.get('executable')||null,workingDir:f.get('working')||null,launchArgs:f.get('args')||null});document.querySelector('#modal-root')!.replaceChildren();await refresh();}catch(err){toast(String(err),true)}}}
function metadataModal(g:Game,m:Metadata|null){modal(`<div class="modal-head"><h2>Metadata · ${esc(g.title)}</h2><button data-close>×</button></div><form id="meta-form"><label>Descrição<textarea name="description">${esc(m?.description||'')}</textarea></label><div class="two"><label>Desenvolvedor<input name="developer" value="${esc(m?.developer||'')}"></label><label>Publisher<input name="publisher" value="${esc(m?.publisher||'')}"></label></div><div class="two"><label>Lançamento<input name="release" value="${esc(m?.release_date||'')}"></label><label>Gêneros<input name="genres" value="${esc(m?.genres||'')}"></label></div><label>Capa (URL/caminho)<input name="cover" value="${esc(m?.cover||'')}"></label><label>Hero (URL/caminho)<input name="hero" value="${esc(m?.hero||'')}"></label><button class="primary">Salvar</button></form>`);(document.querySelector('#meta-form') as HTMLFormElement).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);await invoke('save_metadata',{metadata:{game_id:g.id,description:f.get('description')||null,developer:f.get('developer')||null,publisher:f.get('publisher')||null,release_date:f.get('release')||null,genres:f.get('genres')||null,cover:f.get('cover')||null,hero:f.get('hero')||null,source:'manual',manual:true,updated_at:new Date().toISOString()}});document.querySelector('#modal-root')!.replaceChildren();await selectGame(g.id)}}


const money=(value:number,currency='BRL')=>new Intl.NumberFormat('pt-BR',{style:'currency',currency}).format(value);
async function renderStore(){
 title('Loja');const content=document.querySelector('#content')!;content.innerHTML='<section class="page"><div class="store-loading">Carregando ofertas…</div></section>';
 try{const items=await invoke<StoreCatalogItem[]>('store_catalog');content.innerHTML=`<section class="page"><div class="page-actions"><div><h2>Jogos e ofertas</h2><p>Catálogo da Steam com comparação de preços para o Brasil. Clique em um jogo para consultar as fontes configuradas.</p></div><button id="store-config" class="ghost">Configurar fontes</button></div><div class="store-grid">${items.map(i=>`<button class="store-card" data-store-app="${i.app_id}"><div class="store-cover" data-store-cover="${i.app_id}">${i.cover?`<img src="${esc(i.cover)}" loading="lazy" onerror="this.remove()">`:''}</div><strong>${esc(i.title)}</strong><span>${i.price!==null?money(i.price,i.currency||'BRL'):'Comparar preços'}</span>${i.discount_percent>0?`<b>-${i.discount_percent}%</b>`:''}</button>`).join('')}</div><div id="store-detail" class="store-detail"><p class="muted">Selecione um jogo para ver onde está mais barato.</p></div></section>`;
 (document.querySelector('#store-config') as HTMLButtonElement).onclick=()=>{view='settings';shell();void renderSettings()};
 document.querySelectorAll<HTMLElement>('[data-store-app]').forEach(b=>b.onclick=()=>void renderStoreComparison(b.dataset.storeApp!));
 document.querySelectorAll<HTMLImageElement>('.store-cover img').forEach(img=>{const raw=img.getAttribute('src')||'';if(raw.startsWith('steam-artwork:'))void artworkSrc(raw).then(v=>img.src=v).catch(()=>img.remove())});
 }catch(e){content.innerHTML=`<section class="page"><div class="empty">Não foi possível carregar a loja: ${esc(String(e))}</div></section>`}
}
async function renderStoreComparison(appId:string){const pane=document.querySelector('#store-detail')!;pane.innerHTML='<p class="muted">Consultando Steam, lojas oficiais e keyshops…</p>';try{const c=await invoke<StoreComparison>('store_compare',{appId});pane.innerHTML=`<div class="store-detail-head"><div><h2>${esc(c.title)}</h2><p>Steam AppID ${esc(c.app_id)}</p></div><button id="gg-link" class="ghost">Ver todas no GG.deals</button></div><div class="offer-list">${c.offers.map((o,i)=>`<button data-offer="${i}" class="offer-row ${i===0?'best':''}"><span><b>${esc(o.shop)}</b><small>${o.kind==='keyshop'?'Keyshop':'Loja oficial'}${o.cut?` · -${o.cut}%`:''}</small></span><strong>${money(o.price,o.currency)}</strong>${o.regular&&o.regular>o.price?`<del>${money(o.regular,o.currency)}</del>`:''}</button>`).join('')||'<p class="empty">Nenhuma fonte de preço configurada respondeu para este jogo.</p>'}</div><p class="store-note">${esc(c.note)}</p>`;document.querySelectorAll<HTMLElement>('[data-offer]').forEach(b=>b.onclick=()=>{const o=c.offers[Number(b.dataset.offer)];if(o)void invoke('open_external_url',{url:o.url})});(document.querySelector('#gg-link') as HTMLButtonElement).onclick=()=>void invoke('open_external_url',{url:c.gg_url});}catch(e){pane.innerHTML=`<p class="empty">${esc(String(e))}</p>`}}

async function renderCollections(){title('Coleções');const cols=await invoke<Collection[]>('list_collections');document.querySelector('#content')!.innerHTML=`<section class="page"><div class="page-actions"><p>Organize sua biblioteca sem alterar as instalações.</p><button id="new-col" class="primary">Nova coleção</button></div><div class="cards">${cols.map(c=>`<article><h3>${esc(c.name)}</h3><p>${c.game_count} jogo(s)</p><div><button data-rename="${c.id}" class="ghost">Renomear</button><button data-delete="${c.id}" class="danger">Excluir</button></div></article>`).join('')||'<div class="empty">Nenhuma coleção criada.</div>'}</div></section>`;(document.querySelector('#new-col') as HTMLButtonElement).onclick=async()=>{const n=prompt('Nome da coleção');if(n?.trim()){await invoke('create_collection',{name:n.trim()});void renderCollections()}};document.querySelectorAll<HTMLElement>('[data-rename]').forEach(b=>b.onclick=async()=>{const n=prompt('Novo nome');if(n?.trim()){await invoke('rename_collection',{collectionId:b.dataset.rename,name:n});void renderCollections()}});document.querySelectorAll<HTMLElement>('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Excluir esta coleção?')){await invoke('delete_collection',{collectionId:b.dataset.delete});void renderCollections()}})}
async function renderEmulation(){title('Emulação');const [emus,roms,backups]=await Promise.all([invoke<Emulator[]>('list_emulators'),invoke<Rom[]>('list_roms'),invoke<SaveBackup[]>('list_save_backups')]);document.querySelector('#content')!.innerHTML=`<section class="page"><div class="page-actions"><div><h2>Emuladores</h2><p>Configuração genérica; Ludex não distribui ROMs nem BIOS.</p></div><button id="new-emu" class="primary">Configurar emulador</button></div><div class="cards">${emus.map(e=>`<article><h3>${esc(e.name)}</h3><p>${esc(e.platform)} · ${esc(e.extensions||'extensões personalizadas')}</p><small>${esc(e.executable)}</small>${e.saves_directory?`<button data-save-backup="${e.id}" class="ghost">Backup de saves</button>`:''}</article>`).join('')||'<div class="empty">Nenhum emulador configurado.</div>'}</div>${backups.length?`<div class="page-actions"><h2>Backups de saves <span class="count">${backups.length}</span></h2></div><div class="rom-list">${backups.slice(0,12).map(b=>`<div><span><b>${esc(b.source_path)}</b><small>${date(b.created_at)} · ${esc(b.backup_path)}</small></span><button data-restore-backup="${b.id}" class="ghost">Restaurar</button></div>`).join('')}</div>`:''}<div class="page-actions"><h2>ROMs <span class="count">${roms.length}</span></h2><button id="scan-rom" class="ghost">Escanear pasta</button></div><div class="rom-list">${roms.map(r=>`<div><span><b>${esc(r.title)}</b><small>${esc(r.platform)} · ${esc(r.path)}</small></span><button data-rom="${r.id}" class="primary">JOGAR</button></div>`).join('')||'<p class="empty">Nenhuma ROM importada.</p>'}</div></section>`;(document.querySelector('#new-emu') as HTMLButtonElement).onclick=()=>emulatorModal();(document.querySelector('#scan-rom') as HTMLButtonElement).onclick=()=>romScanModal(emus);document.querySelectorAll<HTMLElement>('[data-save-backup]').forEach(b=>b.onclick=async()=>{const e=emus.find(x=>x.id===b.dataset.saveBackup);if(!e?.saves_directory)return;try{await invoke('backup_save_path',{source:e.saves_directory,emulatorId:e.id});toast('Backup de saves criado.');void renderEmulation()}catch(err){toast(String(err),true)}});document.querySelectorAll<HTMLElement>('[data-restore-backup]').forEach(b=>b.onclick=async()=>{if(!confirm('Restaurar este backup? O Ludex recusa sobrescrever um destino existente.'))return;try{await invoke('restore_save_backup',{backupId:b.dataset.restoreBackup});toast('Backup restaurado.')}catch(err){toast(String(err),true)}});document.querySelectorAll<HTMLElement>('[data-rom]').forEach(b=>b.onclick=async()=>{try{await invoke('launch_rom',{romId:b.dataset.rom});toast('ROM iniciada.')}catch(e){toast(String(e),true)}})}
function emulatorModal(){modal(`<div class="modal-head"><h2>Emulador</h2><button data-close>×</button></div><form id="emu-form"><label>Preset<select name="preset"><option>Personalizado</option>${['RetroArch','Dolphin','PCSX2','RPCS3','PPSSPP','DuckStation','Cemu','Ryujinx','melonDS','mGBA'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Nome<input name="name" required></label><label>Plataforma<input name="platform" required></label><label>Executável<input name="executable" required></label><label>Argumentos <small>use {rom} e {core}</small><input name="args" value="{rom}"></label><label>Extensões<input name="ext"></label><label>ROM folder<input name="romdir"></label><label>BIOS folder<input name="bios"></label><label>Saves folder<input name="saves"></label><label>Core RetroArch<input name="core"></label><button class="primary">Salvar</button></form>`);const form=document.querySelector('#emu-form') as HTMLFormElement;(form.elements.namedItem('preset') as HTMLSelectElement).onchange=async e=>{const n=(e.target as HTMLSelectElement).value;if(n==='Personalizado')return;const p=await invoke<[string,string,string]|null>('emulator_preset',{name:n});if(p){(form.elements.namedItem('name') as HTMLInputElement).value=n;(form.elements.namedItem('platform') as HTMLInputElement).value=p[0];(form.elements.namedItem('args') as HTMLInputElement).value=p[1];(form.elements.namedItem('ext') as HTMLInputElement).value=p[2]}};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);try{await invoke('save_emulator',{emulator:{id:crypto.randomUUID(),name:f.get('name'),platform:f.get('platform'),executable:f.get('executable'),arguments_template:f.get('args'),rom_directory:f.get('romdir')||null,bios_directory:f.get('bios')||null,saves_directory:f.get('saves')||null,extensions:f.get('ext')||'',core:f.get('core')||null,enabled:true}});document.querySelector('#modal-root')!.replaceChildren();void renderEmulation()}catch(err){toast(String(err),true)}}}
function romScanModal(emus:Emulator[]){modal(`<div class="modal-head"><h2>Escanear ROMs</h2><button data-close>×</button></div><form id="rom-form"><label>Pasta<input name="folder" required></label><label>Plataforma<input name="platform" required placeholder="PlayStation 2"></label><label>Emulador<select name="emulator"><option value="">Associar depois</option>${emus.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="recursive" checked> Incluir subpastas</label><button class="primary">Escanear</button></form>`);(document.querySelector('#rom-form') as HTMLFormElement).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);try{const r=await invoke<any>('scan_roms',{folder:f.get('folder'),platform:f.get('platform'),emulatorId:f.get('emulator')||null,recursive:f.has('recursive')});toast(`${r.imported} ROM(s) importada(s), ${r.duplicates} duplicada(s).`);document.querySelector('#modal-root')!.replaceChildren();void renderEmulation()}catch(err){toast(String(err),true)}}}
async function renderSync(){
  title('Sincronização');
  const androidCount=games.filter(g=>gameSources(g).some(s=>s.source==='android')).length;
  const remoteCount=games.filter(g=>gameSources(g).some(s=>['nintendo','playstation','xbox','riot'].includes(s.source))).length;
  document.querySelector('#content')!.innerHTML=`<section class="page"><div class="page-actions"><div><h2>Windows ↔ Android</h2><p class="muted">Compartilhe biblioteca, horas, status e favoritos entre seus aparelhos sem depender de servidor ou scraping.</p></div></div><div class="stat-cards"><article><b>${games.length}</b><span>Jogos locais</span></article><article><b>${androidCount}</b><span>Jogos de Android</span></article><article><b>${remoteCount}</b><span>Jogos de consoles / Riot</span></article></div><div class="settings-panels"><article><h3>Importar do celular</h3><p>Android → Sync → Exportar JSON; envie o arquivo ao Windows e selecione abaixo. O importador reconhece dados Android e backups Ludex Desktop e evita duplicar sessões.</p><input type="file" id="sync-file" accept=".json,application/json" hidden><button id="choose-sync" class="primary">Escolher arquivo JSON</button><p id="sync-result" class="muted"></p></article><article><h3>Exportar para Android</h3><p>Gere um backup JSON do Windows que o aplicativo Android consegue importar em Sync → Importar JSON.</p><button id="download-sync" class="ghost">Salvar backup JSON</button><p class="muted">O arquivo pode incluir títulos, horas e metadados pessoais. Escolha com cuidado onde salvá-lo.</p></article></div><article class="sync-note"><h3>O que sincroniza?</h3><p>Jogos, tempo importado, sessões finalizadas e estado da biblioteca. Alguns recursos próprios do Android (Shizuku, leitura de APKs, Usage Access) continuam sendo executados no celular.</p><p>A biblioteca privada Ren’Py é excluída pela exportação padrão do Android. Não há compartilhamento de rede automático.</p></article></section>`;
  // All locally supported launchers appear in Sync, not only Steam.
  const providerIds=['steam','epic','gog','xbox','ea','ubisoft','battlenet'];
  const providerDescription:Record<string,string>={
    steam:'Jogos instalados; conta e horas históricas com Steam Web API Key.',
    epic:'Jogos instalados via manifests locais do Epic Launcher.',
    gog:'Instalações GOG Galaxy ou jogos DRM-free detectáveis.',
    xbox:'Jogos Xbox / Microsoft Store presentes neste Windows.',
    ea:'Instalações detectáveis do EA App.',
    ubisoft:'Instalações detectáveis do Ubisoft Connect.',
    battlenet:'Instalações detectáveis do Battle.net.'
  };
  const section=document.createElement('section');
  section.className='provider-sync-area';
  section.innerHTML=`<div class="page-actions"><div><h2>Sincronizar launchers deste PC</h2><p class="muted">Buscas locais: Steam, Epic, GOG, Xbox / Game Pass, EA, Ubisoft e Battle.net. Não é necessário conectar contas para encontrar instalações detectáveis.</p></div><button class="primary" id="sync-all-platforms">Sincronizar todos</button></div>
  <div id="provider-sync-results" class="muted" aria-live="polite"></div>
  <div class="provider-grid">${providerIds.map(id=>`<article><div class="provider-head"><h3>${esc(providerLabel(id))}</h3><span class="pill" id="provider-status-${id}">Verificar</span></div><p>${esc(providerDescription[id])}</p><small id="provider-info-${id}">Aguardando diagnóstico</small><div class="provider-foot"><button class="ghost" data-sync-local="${id}">Sincronizar ${esc(providerLabel(id))}</button></div></article>`).join('')}</div>
  <h2>Plataformas vinculadas pelo celular</h2><div class="provider-grid">
  <article><h3>PlayStation Network</h3><p>Horas e jogos do histórico PSN são importados pelo JSON exportado no Android. Sem leitura direta da conta PSN no Windows.</p><button class="ghost" data-import-mobile>Importar JSON Android</button></article>
  <article><h3>Nintendo Switch 1 e 2</h3><p>Tempo de jogo da conta Nintendo coletado no Android e transferido pelo JSON.</p><button class="ghost" data-import-mobile>Importar JSON Android</button></article>
  <article><h3>Xbox / Game Pass (histórico)</h3><p>A busca local detecta instalações Windows; para jogos já jogados e desinstalados, importe o histórico do Android.</p><button class="ghost" data-import-mobile>Importar JSON Android</button></article>
  <article><h3>Riot Games</h3><p>League of Legends via WOL.GG e Valorant via Tracker.gg: horas manuais, sem scraping.</p><button class="ghost" id="sync-riot">Importar horas Riot</button></article>
  <article><h3>Steam (biblioteca completa)</h3><p>A chave Steam Web API permite jogos não instalados; configure-a em Configurações.</p><button class="ghost" id="sync-steam-account">Atualizar conta Steam</button></article>
  </div><p class="muted">Sincronizar launchers locais não importa automaticamente todas as horas históricas de Epic, GOG, EA, Ubisoft ou Battle.net. Onde não existir uma fonte autorizada, o Ludex mantém apenas o tempo que conseguiu medir ou importar.</p>`;
  const host=document.querySelector<HTMLElement>('#content .page')!;
  host.prepend(section);
  document.querySelectorAll<HTMLButtonElement>('[data-import-mobile]').forEach(b=>b.onclick=()=>document.querySelector<HTMLInputElement>('#sync-file')?.click());
  document.querySelector<HTMLButtonElement>('#sync-riot')!.onclick=()=>riotModal();
  document.querySelector<HTMLButtonElement>('#sync-steam-account')!.onclick=async()=>{
    try{
      const status=await invoke<SteamAccountStatus>('steam_account_status');
      if(!status.api_key_configured){toast('Configure sua Steam Web API Key em Configurações.',true);return}
      const result=await invoke<{games_found:number;games_created:number}>('sync_steam_account');
      toast(`Steam: ${result.games_found} jogos na conta, ${result.games_created} novos.`);await refresh(true,false)
    }catch(error){toast('Steam: '+String(error),true)}
  };
  const results=document.querySelector<HTMLElement>('#provider-sync-results')!;
  async function updateProviderStatuses(){
    try{
      const statuses=await invoke<Provider[]>('provider_statuses');
      for(const s of statuses){
        const badge=document.querySelector('#provider-status-'+s.id);
        const info=document.querySelector('#provider-info-'+s.id);
        if(badge){badge.textContent=s.detected?'Detectado':'Não detectado';badge.classList.toggle('ok',s.detected)}
        if(info)info.textContent=`${s.games_found} instalações · último sync: ${date(s.last_sync)}. ${s.message}`;
      }
    }catch(error){if(results.isConnected)results.textContent='Diagnóstico dos launchers indisponível: '+String(error)}
  }
  document.querySelectorAll<HTMLButtonElement>('[data-sync-local]').forEach(button=>button.onclick=async()=>{
    const provider=button.dataset.syncLocal!;
    button.disabled=true;button.textContent='Sincronizando…';
    try{
      const result=await invoke<{games_found:number;games_created:number}>('sync_provider',{provider});
      if(results.isConnected)results.textContent=`${providerLabel(provider)}: ${result.games_found} encontrados, ${result.games_created} novos.`;
      await refresh(true,false);
      void updateProviderStatuses()
    }catch(error){if(results.isConnected)results.textContent=`${providerLabel(provider)}: ${String(error)}`;toast(String(error),true)}
    finally{button.disabled=false;button.textContent='Sincronizar '+providerLabel(provider)}
  });
  const allButton=document.querySelector<HTMLButtonElement>('#sync-all-platforms')!;
  allButton.onclick=async()=>{
    allButton.disabled=true;allButton.textContent='Sincronizando todas…';
    try{
      const outcomes=await invoke<SyncOutcome[]>('sync_all_providers');
      if(results.isConnected)results.innerHTML=outcomes.map(item=>`<div class="${item.success?'ok':'info'}">${esc(providerLabel(item.provider))}: ${item.success?`${item.games_found} jogos (${item.games_created} novos)`:esc(item.message)}</div>`).join('');
      await refresh(true,false);
      void updateProviderStatuses();
      toast(`${outcomes.filter(item=>item.success).length}/${outcomes.length} launchers sincronizados.`)
    }catch(error){if(results.isConnected)results.textContent='Erro no sincronizador: '+String(error);toast(String(error),true)}
    finally{allButton.disabled=false;allButton.textContent='Sincronizar todos'}
  };
  void updateProviderStatuses();
  const input=document.querySelector<HTMLInputElement>('#sync-file')!;
  const choose=document.querySelector<HTMLButtonElement>('#choose-sync')!;
  choose.onclick=()=>input.click();
  input.onchange=async()=>{
    const file=input.files?.[0];if(!file)return;
    if(file.size>32*1024*1024){toast('O JSON deve ter até 32 MB.',true);return}
    choose.disabled=true;choose.textContent='Importando…';
    try{
      const json=await file.text();
      const root=JSON.parse(json);
      if(root?.version!==1||!['ludex-backup','ludex-mobile-sync'].includes(root.format))throw Error('Formato não reconhecido');
      const result=await invoke<{inserted:number;updated:number;skipped:number}>('import_sync_json',{json});
      document.querySelector('#sync-result')!.textContent=`Importação concluída: ${result.inserted} jogos novos, ${result.updated} atualizados, ${result.skipped} ignorados.`;
      await refresh(true,false);
      toast('Biblioteca importada. As horas foram atualizadas.');
    }catch(error){toast('Não foi possível importar o arquivo: '+String(error),true)}
    finally{choose.disabled=false;choose.textContent='Escolher arquivo JSON';input.value=''}
  };
  document.querySelector<HTMLButtonElement>('#download-sync')!.onclick=async()=>{
    try{
      const json=await invoke<string>('export_backup_json');
      const blob=new Blob([json],{type:'application/json;charset=utf-8'});
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');
      a.href=url;a.download='ludex-windows-sync-'+new Date().toISOString().slice(0,10)+'.json';
      document.body.appendChild(a);a.click();a.remove();
      window.setTimeout(()=>URL.revokeObjectURL(url),30000);
      toast('Backup JSON preparado.');
    }catch(e){toast(String(e),true)}
  };
}

async function renderStats(){title('Estatísticas');const s=await invoke<Stats>('library_stats');const bars=(v:{name:string;seconds:number}[])=>v.map(x=>`<div class="bar-row"><span>${esc(x.name)}</span><div><i style="width:${Math.max(3,Math.round(x.seconds/Math.max(...v.map(y=>y.seconds),1)*100))}%"></i></div><b>${dur(x.seconds)}</b></div>`).join('');document.querySelector('#content')!.innerHTML=`<section class="page"><div class="stat-cards"><article><b>${dur(s.tracked_seconds)}</b><span>Tempo Ludex</span></article><article><b>${dur(s.imported_seconds)}</b><span>Importado</span></article><article><b>${s.library_games}</b><span>Biblioteca</span></article><article><b>${s.never_played}</b><span>Nunca jogados</span></article><article><b>${dur(s.last_14_seconds)}</b><span>2 semanas</span></article><article><b>${dur(s.last_30_seconds)}</b><span>30 dias</span></article></div><div class="stat-columns"><article><h3>Mais jogados</h3>${bars(s.top_games)}</article><article><h3>Por provider</h3>${bars(s.by_provider)}</article><article><h3>Por plataforma</h3>${bars(s.by_platform)}</article></div><article class="timeline"><h3>Meses</h3><div>${s.monthly.slice().reverse().map(m=>`<span title="${esc(m.label)} · ${dur(m.seconds)}" style="height:${Math.max(8,m.seconds/Math.max(...s.monthly.map(x=>x.seconds),1)*140)}px"></span>`).join('')}</div></article></section>`}
async function renderSettings(){title('Configurações');const ps=await invoke<Provider[]>('provider_statuses');let update:UpdateInfo|null=null;let steamAccount:SteamAccountStatus|null=null;let storeSettings:StoreSettings|null=null;try{update=await invoke<UpdateInfo>('check_for_updates')}catch{}try{steamAccount=await invoke<SteamAccountStatus>('steam_account_status')}catch{}try{storeSettings=await invoke<StoreSettings>('store_settings')}catch{}document.querySelector('#content')!.innerHTML=`<section class="page"><h2>Atualizações</h2><div class="settings-panels"><article><div class="provider-head"><div><h3>Ludex ${esc(update?.current_version||'')}</h3><p>${update?.available?`Versão ${esc(update.latest_version||'')} disponível.`:'Você está na versão mais recente publicada.'}</p></div><span class="pill ${update?.available?'':'ok'}">${update?.available?'Atualização disponível':'Atualizado'}</span></div>${update?.notes?`<p class="muted">${esc(update.notes.slice(0,500))}</p>`:''}<button id="app-update" class="${update?.available?'primary':'ghost'}">${update?.available?'Baixar e instalar':'Verificar novamente'}</button><small>As próximas versões são baixadas pelo próprio Ludex a partir das Releases oficiais do GitHub.</small></article></div><h2>Conta Steam</h2><div class="settings-panels"><article><h3>Biblioteca completa</h3><p>Conta detectada: <b>${esc(steamAccount?.steam_id||'não detectada')}</b> · ${steamAccount?.owned_games||0} jogos Steam conhecidos.</p><p class="muted">Para importar também os jogos não instalados, configure uma Steam Web API key. Ela fica protegida pelo DPAPI do seu usuário do Windows.</p><label>Steam Web API key<input id="steam-api-key" type="password" placeholder="Cole a chave; deixe vazio para manter a atual"></label><div><button id="save-steam-key" class="ghost">Salvar chave</button><button id="sync-steam-account" class="primary" ${steamAccount?.api_key_configured?'':'disabled'}>Importar biblioteca completa</button><button id="steam-key-help" class="text-btn">Obter chave</button></div><small>Último sync da conta: ${date(steamAccount?.last_sync||null)}</small></article><article><h3>Fontes da Loja</h3><p>Steam funciona sem chave. ITAD adiciona lojas oficiais individuais (incluindo Nuuvem quando disponível no Brasil); GG.deals adiciona o menor preço entre lojas oficiais e keyshops.</p><label>GG.deals API key<input id="gg-key" type="password" placeholder="${storeSettings?.ggdeals_configured?'Configurada · cole para substituir':'Opcional'}"></label><label>IsThereAnyDeal API key<input id="itad-key" type="password" placeholder="${storeSettings?.itad_configured?'Configurada · cole para substituir':'Opcional'}"></label><label>País<input id="store-country" value="${esc(storeSettings?.country||'BR')}" maxlength="2"></label><button id="save-store-keys" class="ghost">Salvar fontes da Loja</button><p class="muted">Eneba e Instant Gaming não oferecem uma API pública de preços para consumidores; o Ludex não faz scraping. Quando cobertas pelo GG.deals, entram no menor preço de keyshops e no link detalhado.</p></article></div><h2>Riot Games</h2><div class="settings-panels"><article><h3>League of Legends e VALORANT</h3><p>Importe as horas históricas consultadas no WOL.GG (LoL) ou Tracker.gg (VALORANT). Sem scraping, dados privados ou login de terceiros.</p><button id="riot-import" class="primary">Importar horas Riot</button></article></div><h2>Providers</h2><div class="provider-grid">${ps.map(p=>`<article><div class="provider-head"><h3>${esc(p.name)}</h3><span class="pill ${p.detected?'ok':''}">${p.detected?'Detectado':'Não detectado'}</span></div><p>${esc(p.message)}</p><small>${esc(p.root_path||'Sem caminho local exposto')}</small><div class="provider-foot"><span>${p.games_found} jogo(s) · sync ${date(p.last_sync)}</span><button data-sync="${p.id}" class="ghost">Sincronizar</button></div></article>`).join('')}</div><h2>Dados e sincronização</h2><div class="settings-panels"><article><h3>Sync por arquivo</h3><p>Exporta um bundle JSON versionado para mover entre Desktop e Android. IDs de sessão evitam duplicidade.</p><div><button id="export-json" class="primary">Exportar JSON</button><button id="import-json" class="ghost">Importar JSON</button></div><textarea id="sync-json" placeholder="O JSON exportado aparece aqui. Cole um bundle para importar."></textarea></article><article><h3>Backup do banco</h3><p>Cria uma cópia SQLite consistente na pasta local de backups do Ludex.</p><button id="db-backup" class="ghost">Criar backup</button><p id="backup-path" class="muted"></p></article></div><h2>Privacidade</h2><p class="muted">Biblioteca, sessões e metadata permanecem locais. Não há telemetria obrigatória nem servidor proprietário.</p></section>`;(document.querySelector('#riot-import') as HTMLButtonElement).onclick=()=>riotModal();document.querySelectorAll<HTMLElement>('[data-sync]').forEach(b=>b.onclick=async()=>{b.textContent='Sincronizando…';try{const r=await invoke<any>('sync_provider',{provider:b.dataset.sync});toast(`${r.games_found} encontrados · ${r.games_created} novos.`);await refresh();void renderSettings()}catch(e){toast(String(e),true);b.textContent='Sincronizar'}});const updateButton=document.querySelector<HTMLButtonElement>('#app-update');if(updateButton)updateButton.onclick=async()=>{if(!update?.available){updateButton.textContent='Verificando…';void renderSettings();return}if(!confirm(`Atualizar o Ludex para ${update.latest_version}? O app será fechado durante a instalação.`))return;updateButton.disabled=true;updateButton.textContent='Baixando atualização…';try{await invoke('install_update')}catch(e){updateButton.disabled=false;updateButton.textContent='Baixar e instalar';toast(String(e),true)}};const saveSteam=document.querySelector<HTMLButtonElement>('#save-steam-key');if(saveSteam)saveSteam.onclick=async()=>{const key=(document.querySelector('#steam-api-key') as HTMLInputElement).value;try{await invoke('save_steam_web_api_key',{key});toast('Steam Web API key salva com proteção do Windows.');void renderSettings()}catch(e){toast(String(e),true)}};const syncAccount=document.querySelector<HTMLButtonElement>('#sync-steam-account');if(syncAccount)syncAccount.onclick=async()=>{syncAccount.disabled=true;syncAccount.textContent='Importando…';try{const r=await invoke<any>('sync_steam_account');toast(`${r.games_found} jogos encontrados · ${r.games_created} novos.`);await refresh();void renderSettings()}catch(e){toast(String(e),true);syncAccount.disabled=false;syncAccount.textContent='Importar biblioteca completa'}};const help=document.querySelector<HTMLButtonElement>('#steam-key-help');if(help)help.onclick=()=>void invoke('open_external_url',{url:'https://steamcommunity.com/dev/apikey'});const storeSave=document.querySelector<HTMLButtonElement>('#save-store-keys');if(storeSave)storeSave.onclick=async()=>{const gg=(document.querySelector('#gg-key') as HTMLInputElement).value.trim();const itad=(document.querySelector('#itad-key') as HTMLInputElement).value.trim();const country=(document.querySelector('#store-country') as HTMLInputElement).value.trim();try{await invoke('save_store_settings',{ggdealsKey:gg||null,itadKey:itad||null,country});toast('Fontes da Loja salvas.');void renderSettings()}catch(e){toast(String(e),true)}};(document.querySelector('#export-json') as HTMLButtonElement).onclick=async()=>{(document.querySelector('#sync-json') as HTMLTextAreaElement).value=await invoke('export_backup_json')};(document.querySelector('#import-json') as HTMLButtonElement).onclick=async()=>{const json=(document.querySelector('#sync-json') as HTMLTextAreaElement).value;if(!json.trim())return;try{const r=await invoke<any>('import_sync_json',{json});toast(`${r.inserted} registros importados.`);await refresh()}catch(e){toast(String(e),true)}};(document.querySelector('#db-backup') as HTMLButtonElement).onclick=async()=>{try{const p=await invoke<string>('backup_database');document.querySelector('#backup-path')!.textContent=p;toast('Backup criado.')}catch(e){toast(String(e),true)}}}
async function renderDiagnostics(){title('Diagnóstico');const [d,p]=await Promise.all([invoke<Diagnostic[]>('diagnostics'),invoke<Provider[]>('provider_statuses')]);document.querySelector('#content')!.innerHTML=`<section class="page"><div class="diagnostic-summary"><b>${p.filter(x=>x.detected).length}/${p.length}</b><span>providers detectados</span></div><div class="diag-list">${d.map(x=>`<div class="${x.level}"><b>${esc(x.area)}</b><span>${esc(x.message)}</span></div>`).join('')}${p.map(x=>`<div class="${x.detected?'ok':'info'}"><b>${esc(x.name)}</b><span>${esc(x.message)}${x.root_path?` · ${esc(x.root_path)}`:''}</span></div>`).join('')}</div><button id="copy-diag" class="ghost">Copiar diagnóstico</button></section>`;(document.querySelector('#copy-diag') as HTMLButtonElement).onclick=()=>navigator.clipboard.writeText(JSON.stringify({diagnostics:d,providers:p},null,2)).then(()=>toast('Diagnóstico copiado.'))}
async function renderView(){if(['library','recent','favorites','installed'].includes(view))renderLibrary();else if(view==='libraries')renderLibrariesHub();else if(view==='store')await renderStore();else if(view==='collections')await renderCollections();else if(view==='emulation')await renderEmulation();else if(view==='stats')await renderStats();else if(view==='sync')await renderSync();else if(view==='settings')await renderSettings();else if(view==='diagnostics')await renderDiagnostics()}
const fingerprint=(items:Game[])=>items.map(g=>[g.id,g.title,g.favorite,g.status,g.total_seconds,g.installed,g.active,g.last_played_at,g.session_count,g.providers.join(',')].join('~')).join('|');
async function refresh(keep=false,forceRender=true){const [next,sources]=await Promise.all([invoke<Game[]>('list_games'),invoke<LibrarySource[]>('list_library_sources')]);const nextFingerprint=fingerprint(next)+'|'+sources.map(s=>[s.game_id,s.source,s.seconds,s.private].join(':')).join(';');const changed=nextFingerprint!==gameFingerprint;games=next;librarySources=sources;rebuildSourceIndex();gameFingerprint=nextFingerprint;if(!keep&&!selected)selected=games[0]?.id||null;if(forceRender||changed){await loadCoverIndex();await renderView()}}
function toast(message:string,error=false){let t=document.querySelector<HTMLDivElement>('#toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=message;t.className=error?'error':'';t.classList.add('show');setTimeout(()=>t?.classList.remove('show'),3200)}

async function bootstrap(){shell();await loadCoverIndex();await refresh();window.setTimeout(async()=>{try{const u=await invoke<UpdateInfo>('check_for_updates');if(u.available)toast(`Ludex ${u.latest_version} disponível em Configurações.`)}catch{}},1800)}
void bootstrap();window.setInterval(()=>{if(['library','recent','favorites','installed'].includes(view))void refresh(true,false)},15000);
